// ---- earthquakes near your sites: distance and magnitude in code -------------------------------------------
const num = (v) => { const n = Number(String(v ?? '').trim()); return String(v ?? '').trim() !== '' && Number.isFinite(n) ? n : NaN; };
// great-circle distance in km (haversine, Earth radius 6371 km)
function distanceKm(lat1, lon1, lat2, lon2) {
  const rad = (d) => (d * Math.PI) / 180;
  const a = Math.sin(rad(lat2 - lat1) / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(rad(lon2 - lon1) / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.min(1, Math.sqrt(a)));
}

// the Sites tab: name, lat, lon, contact, and optional per-site radius_km / min_magnitude
function readSites(rows, cfg) {
  const sites = [], problems = [];
  rows.forEach((r, i) => {
    const name = String(r.site ?? '').trim();
    if (!name && String(r.lat ?? '').trim() === '' && String(r.lon ?? '').trim() === '') return; // an empty row
    const lat = num(r.lat), lon = num(r.lon);
    if (!name) problems.push('row ' + (i + 2) + ': no site name');
    if (!(lat >= -90 && lat <= 90) || !(lon >= -180 && lon <= 180)) { problems.push('row ' + (i + 2) + ' (' + (name || '?') + '): lat / lon are not valid numbers'); return; }
    sites.push({ name, lat, lon, contact: String(r.contact ?? '').trim(),
      radius_km: num(r.radius_km) > 0 ? num(r.radius_km) : Number(cfg.radius_km), min_magnitude: Number.isFinite(num(r.min_magnitude)) ? num(r.min_magnitude) : Number(cfg.min_magnitude) });
  });
  return { sites, problems };
}

// which (earthquake, site) pairs need a safety check, and which were already sent
function matchQuakes(feed, sites, sentKeys) {
  const out = [];
  for (const f of feed?.features ?? []) {
    const p = f.properties ?? {}, [lon, lat, depth] = f.geometry?.coordinates ?? [];
    if (!(Number.isFinite(lat) && Number.isFinite(lon) && Number.isFinite(p.mag))) continue;
    if (p.status === 'deleted' || (p.type && p.type !== 'earthquake')) continue;
    const near = [];
    for (const s of sites) {
      const d = distanceKm(s.lat, s.lon, lat, lon);
      const key = f.id + '|' + s.name;
      if (p.mag >= s.min_magnitude && d <= s.radius_km && !sentKeys.has(key)) near.push({ ...s, distance_km: Math.round(d), key });
    }
    if (near.length) out.push({ id: f.id, mag: p.mag, place: p.place ?? '', time: p.time, depth_km: Number.isFinite(depth) ? Math.round(depth) : null,
      url: p.url ?? '', tsunami: p.tsunami === 1, status: p.status ?? '', near: near.sort((a, b) => a.distance_km - b.distance_km) });
  }
  return out.sort((a, b) => b.mag - a.mag);
}

function fmtTime(ms, tz) {
  try { return new Intl.DateTimeFormat('sv-SE', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(ms)); }
  catch (e) { return new Date(ms).toISOString().slice(0, 16).replace('T', ' ') + ' UTC'; }
}
const mention = (c) => (/^[UW][A-Z0-9]{6,}$/.test(c) ? '<@' + c + '>' : c);

function message(q, cfg) {
  const ja = String(cfg.language || 'en').toLowerCase().startsWith('ja');
  const when = fmtTime(q.time, cfg.timezone || 'UTC');
  const sites = q.near.map((s) => '• ' + s.name + (ja ? ' — 約' + s.distance_km + ' km' : ' — about ' + s.distance_km + ' km') + (s.contact ? (ja ? '（担当 ' : ' (contact ') + mention(s.contact) + (ja ? '）' : ')') : '')).join('\n');
  if (ja) return ':rotating_light: *地震（USGS）M' + q.mag + '*｜' + when + '（' + (cfg.timezone || 'UTC') + '）｜' + q.place + (q.depth_km !== null ? '｜深さ ' + q.depth_km + ' km' : '') +
    '\n近くの拠点：\n' + sites + '\n*安否と被害の有無を、このスレッドに返信してください。*' + (q.tsunami ? '\n:warning: USGS の津波の印が付いています。津波の情報は、気象庁などの公式の発表で確かめてください。' : '') +
    '\n_マグニチュード（規模）と、震源からの直線距離で判定しています。震度（揺れの強さ）ではありません。USGS の速報値で、あとで変わることがあります。_ ' + q.url;
  return ':rotating_light: *Earthquake (USGS) M' + q.mag + '* | ' + when + ' (' + (cfg.timezone || 'UTC') + ') | ' + q.place + (q.depth_km !== null ? ' | depth ' + q.depth_km + ' km' : '') +
    '\nSites nearby:\n' + sites + '\n*Please reply in this thread: is everyone safe, any damage?*' + (q.tsunami ? '\n:warning: USGS has a tsunami flag on this event. Check your official local warnings.' : '') +
    '\n_Judged by magnitude and straight-line distance from the epicentre, not by local shaking intensity. USGS values are preliminary and may change._ ' + q.url;
}

const cfg = $('Config').first().json;
const { sites, problems } = readSites($('Read Sites tab').all().map((i) => i.json), cfg);
// a wrong coordinate must not silently remove a site from the watch
if (problems.length) throw new Error('Fix the Sites tab: ' + problems.join('; '));
if (!sites.length) throw new Error('The Sites tab has no site yet (columns: site, lat, lon, contact, radius_km, min_magnitude).');
const feed = $('Get earthquakes (USGS)').first().json;
if (!Array.isArray(feed.features)) throw new Error('The USGS feed could not be read: ' + JSON.stringify(feed).slice(0, 200));
const sent = new Set($('Read Alerts tab').all().map((i) => String(i.json.alert_key ?? '')).filter(Boolean));
const quakes = matchQuakes(feed, sites, sent);
return quakes.map((q) => ({ json: { ...q, text: message(q, cfg) } }));

// one row per (earthquake, site): the Alerts tab is what stops a second message for the same pair
const qs = $('Match quakes and sites').all().map((i) => i.json);
const now = $now.toISO();
return qs.flatMap((q) => q.near.map((s) => ({ json: { alert_key: s.key, event_id: q.id, site: s.name, magnitude: q.mag, distance_km: s.distance_km, place: q.place,
  event_time: new Date(q.time).toISOString(), sent_at: now, usgs_url: q.url } })));
